<?php require_once __DIR__.'/../../includes/bootstrap.php'; require_role('admin'); $id=(int)($_GET['id']??0); $q=$pdo->prepare('SELECT k.*,u.username FROM kegiatan k LEFT JOIN users u ON u.id_kegiatan=k.id_kegiatan WHERE k.id_kegiatan=?');$q->execute([$id]);$k=$q->fetch();if(!$k){http_response_code(404);exit('Kegiatan tidak ditemukan.');}$p=$pdo->prepare('SELECT * FROM petugas WHERE id_kegiatan=? AND deleted_at IS NULL ORDER BY nama_petugas');$p->execute([$id]);$petugas=$p->fetchAll();page_header('Detail Kegiatan'); ?>
