-4 h-100"><h2 class="h5 fw-bold">Modul Kegiatan</h2><p class="small text-secondary">Fitur akan aktif sesuai tujuan akhir kegiatan.</p><?php if(in_array($k['tujuan_akhir'],['lpd','keduanya'],true)):?><a class="btn btn-outline-primary mb-2" href="<?=APP_BASE_URL?>/admin/lpd/index.php?id=<?=$id?>">Kelola LPD</a><?php endif;?><?php if(in_array($k['tujuan_akhir'],['kwitansi','keduanya'],true)):?><a class="btn btn-outline-primary" href="<?=APP_BASE_URL?>/admin/kwitansi/index.php?id=<?=$id?>">Kelola Kwitansi</a><?php endif;?></div></div></div>
